import * as D from './content.mjs?v=20';
import * as E from './engine.mjs?v=20';
import * as Old from './panels.mjs?v=20';
import * as A from './adventure-panels.mjs?v=20';
import {roomLayout} from './layouts.mjs?v=20';
import {roomPortals,abilitySet,abilityAvailable} from './world.mjs?v=20';
import {icon,itemArt,portrait,esc,fmt,percent,tabs,section} from './ui-art.mjs?v=20';
export const statText=stats=>Object.entries(stats).filter(([,v])=>v).map(([id,n])=>`${n>0?'+':''}${['attack','defense','health'].includes(id)?Number(n.toFixed(2)):percent(n)} ${id==='health'?'HP':id}`).join(' · ')||'No bonuses';
const btn=(label,attrs='',disabled=false)=>`<button ${attrs} ${disabled?'disabled':''}>${label}</button>`;
const mini=(label,value)=>`<div class="stat-row"><span>${label}</span><strong>${value}</strong></div>`;
const note=text=>`<p class="ui-note">${text}</p>`;
export function sources(id){const out=[];for(const r of D.RECIPES)if(r.output===id||r.equipment===id)out.push({text:`${r.name} · ${r.station}`,recipe:r.id});for(const[town,d]of Object.entries(D.TOWN_SHOPS))if(d.stock.some(r=>r[0]===id))out.push({text:d.name,shop:town});for(const e of Object.values(D.ENEMIES))for(const d of e.loot)if(d.id===id)out.push({text:`${e.name} · ${percent(d.chance)}`,enemy:e.id});if(D.WORLD_LOOT.some(d=>d.id===id))out.push({text:'Any World One enemy · '+percent(D.WORLD_LOOT.find(d=>d.id===id).chance)});if(D.GLOBAL_LOOT.some(d=>d.id===id))out.push({text:'Any enemy · '+percent(D.GLOBAL_LOOT.find(d=>d.id===id).chance)});for(const q of D.STORY)if(q.reward.items?.[id])out.push({text:q.name+' quest',npc:q.giver});if(D.ANVIL_PRODUCTS[id])out.push({text:'Passive anvil production'});for(const a of D.AREAS)if(a.resources.some(r=>r.includes(id)))out.push({text:a.name+' · gathering'});if(id.startsWith('world-token-'))out.push({text:'Complete the named NPC’s three quests'});if(id.startsWith('statue-'))out.push({text:D.STATUES[id.slice(7)]?.source||'World One gathering and combat'});return out;}
export function characterStats(s,c){const range=E.damageRange(s,c),e=E.enemyFor(c);return section('Character',`<div class="sheet-identity">${portrait(c)}<div><strong>${esc(c.name)}</strong><span>${c.class?D.CLASSES[c.class].name:'Beginner'} · Lv ${c.level}</span><small>${esc(roomLayout(c.area,c.zone,c.activity==='boss',c.secret).title)}</small></div></div><div class="sheet-stats">${mini('HP',`${fmt(c.hp)} / ${E.maxHp(c)}`)}${mini('MP',`${Math.floor(c.mp)} / ${E.maxMana(c)}`)}${mini('Damage',range.join(' – '))}${mini('Accuracy',Math.round(E.accuracy(c)))}${mini('Defense',Number(E.defense(s,c).toFixed(2)))}${mini('Critical chance',percent(E.critChance(c)))}${mini('Attack interval',E.attackInterval(c).toFixed(2)+'s')}${mini('Movement',Math.round(E.movementSpeed(c)))}${mini('AFK bonus',percent((s.merits.afk||0)*.05+(c.accountBonuses?.afk||0)))}</div><div class="sheet-skill-list">${Object.entries(D.SKILLS).map(([id,name])=>`<span>${name}<b>${E.skillLevel(c,id)}</b></span>`).join('')}</div><div class="coin-purse">${icon('coin')} ${E.money(s.coins)} ${icon('gem')} ${fmt(s.gems)}</div>`,'character-sheet');}
export function inventory(s,c,view={}){const bank=E.storageAccess(c),storageMode=bank&&view.storage!==false,bag=E.bagSlots(c),chest=E.chestSlots(s),tab=view.tab||'equipment',source=bank&&view.source==='chest'?'chest':'bag',grid=source==='bag'?bag:chest,t=grid[view.index],gear=t?.uid?(source==='bag'?c.packGear:s.armory).find(g=>g.uid===t.uid):null,id=gear?.base||t?.id,locked=source==='bag'&&c.lockedSlots.includes(view.index);
 const cells=(arr,source,page)=>`<div class="inventory-grid" data-grid="${source}">${arr.slice(page*16,page*16+16).map((t,j)=>{const i=page*16+j,g=t?.uid?(source==='bag'?c.packGear:s.armory).find(g=>g.uid===t.uid):null,id=g?.base||t?.id,l=source==='bag'&&c.lockedSlots.includes(i);return`<button class="inventory-slot rarity-${D.ITEMS[id]?.rarity||'common'} ${t?'':'empty-cell'} ${l?'slot-locked':''} ${view.source===source&&view.index===i?'slot-selected':''}" data-inv-slot="${i}" data-source="${source}" draggable="${!!t&&!l}" data-tooltip="${id?esc(D.ITEMS[id].name):'Empty slot'}" aria-label="${source==='bag'?'Backpack':'Chest'} slot ${i+1}: ${D.ITEMS[id]?esc(D.ITEMS[id].name)+(t.qty?' × '+fmt(t.qty):''):'empty'}${l?', locked':''}"><span class="slot-number">${i+1}</span>${id?itemArt(id):'<span class="slot-empty">+</span>'}${t?.qty?`<b>${fmt(t.qty)}</b>`:''}${l?'<span class="slot-padlock">◆</span>':''}</button>`;}).join('')}</div><div class="inventory-pages">${Array.from({length:Math.ceil(arr.length/16)},(_,i)=>btn(String(i+1),`data-inv-page="${i}" data-source="${source}" class="${i===page?'primary':''}"`)).join('')}</div>`;
 const slotIcon={weapon:'sword',head:'helm',body:'body',legs:'legs',feet:'boot',charm:'gem',ring:'ring',ring2:'ring',cape:'cape',trophy:'trophy',pick:'pick',axe:'axe'};
 const gearSlots=Object.entries(D.GEAR_SLOTS).filter(([id])=>tab==='tools'?['pick','axe'].includes(id):!['pick','axe'].includes(id));
 let equip=tab==='food'?A.food(c):tab==='capacity'?`<div class="capacity-list">${Object.entries(E.CARRY_TYPES).map(([type,name])=>`<h4>${name} · ${E.stackLimit(c,{mining:'copper',logging:'oak',materials:'moss-slime',food:'bread'}[type])}/stack</h4>${Object.entries(D.CAPACITY_BAGS).filter(([,d])=>d.type===type).map(([id,d])=>`<div class="capacity-entry">${itemArt(id)}<span>${d.name}<small>+${d.bonus} per stack</small></span>${c.usedCapacityBags.includes(id)?'<b>USED</b>':btn('USE',`data-capacity-bag="${id}"`,!c.bag[id])}</div>`).join('')}`).join('')}<p class="ui-note">Different pouch tiers stack. Each exact pouch is consumed once per character. Extra-slot bags are separate.</p></div>`:`<div class="paperdoll">${portrait(c)}<div class="worn-grid">${gearSlots.map(([slot,name])=>{const item=c.loadout[slot];return`<button class="worn-slot ${view.worn===slot?'slot-selected':''}" data-inv-worn="${slot}" aria-label="${name}: ${item?D.ITEMS[item.base].name:'Empty'}">${item?itemArt(item.base):icon(slotIcon[slot],'#a29479','item-art')}<small>${name}</small></button>`;}).join('')}</div></div>${note(tab==='tools'?'Tools stay equipped alongside your combat gear.':'Select an equipped item to inspect it. Both rings share the same equipment type.')}`;
 let detail=note('Select a slot to inspect its item. Drag slots on PC, or choose Move / split and tap a destination on mobile.');
 const worn=c.loadout[view.worn];if(worn)detail=itemDetail(s,c,worn.base,worn)+btn('UNEQUIP',`data-unequip="${view.worn}"`);
 else if(id){const def=D.EQUIPMENT[id];detail=itemDetail(s,c,id,gear)+`<div class="item-actions"><label>Quantity<input id="inventory-quantity" type="number" inputmode="numeric" min="1" max="${t.qty||1}" value="${Math.min(view.quantity||t.qty||1,t.qty||1)}"></label>${source==='bag'?btn(locked?'UNLOCK':'LOCK',`data-inv-lock="${view.index}"`)+btn(view.moving?'PICK A SLOT':'MOVE / SPLIT','data-inv-move=""',locked)+(gear?btn('EQUIP',`data-equip="${gear.uid}"`,locked||def.class&&c.class!==def.class):'')+(D.FOODS[id]?c.foodSlots.map((f,i)=>btn('FOOD '+(i+1),`data-food-equip="${i}" data-index="${view.index}"`,!!f||locked)).join(''):'')+(D.POTIONS[id]?btn('DRINK',`data-drink="${id}"`):'')+(id==='tonic'?btn('HEAL','data-heal=""'):'')+(D.EXPANSIONS[id]?btn('USE EXPANSION',`data-expand="${id}"`,(D.EXPANSIONS[id].target==='bag'?c.usedExpansions:s.usedChestExpansions).includes(id)):'')+(D.CAPACITY_BAGS[id]?btn('USE POUCH',`data-capacity-bag="${id}"`,c.usedCapacityBags.includes(id)):''):btn(view.moving?'PICK A SLOT':'MOVE / SPLIT','data-inv-move=""',!bank)}${btn(source==='bag'?'DEPOSIT':'WITHDRAW','data-inv-transfer=""',!bank||locked)}${source==='bag'?btn(view.confirmDrop?'CONFIRM DROP':'DROP','data-inv-drop="" class="danger"',locked):''}</div>${view.confirmDrop?note('This places the selected quantity on the ground beside you.'):''}`;}
 const page=Math.min(view.page||0,Math.ceil(bag.length/16)-1),chestPage=Math.min(view.chestPage||0,Math.ceil(chest.length/16)-1);
 return`<div class="inventory-topline"><strong>${E.bagUsed(c)} / ${E.bagCapacity(c)} backpack slots</strong>${btn('CARDS','data-panel="cards"')}${btn('AFK INFO','data-panel="afk"')}${bank?btn(storageMode?'CHARACTER VIEW':'STORAGE VIEW','data-inv-storage=""'):btn('FIND CHEST','data-find-storage=""')}</div><div class="inventory-layout">${storageMode?section('Universal Storage',`<strong>${E.chestUsed(s)} / ${E.chestCapacity(s)} slots</strong><div class="save-actions">${btn('DEPOSIT ALL','data-deposit-all=""')}</div>${cells(chest,'chest',chestPage)}${note('Shared across all town chests. Select a slot to withdraw. 999 items per stack.')}`,'storage-side'):characterStats(s,c)}${section('Equipped',tabs([['equipment','EQUIPS'],['tools','TOOLS'],['food','FOODS'],['capacity','BAGS']],tab,'data-inv-tab')+equip,'inventory-character')}${section('Items',`<div class="inventory-toolbar">${btn(view.lockMode?'LOCKING ON':'LOCK SLOTS',`data-inv-lock-mode="" aria-pressed="${!!view.lockMode}"`)}${btn('SORT','data-inv-sort=""')}</div>${cells(bag,'bag',page)}${note(view.moving?'Tap a destination slot. The quantity controls how much moves.':view.lockMode?'Tap backpack slots to toggle their locks.':'Locks protect moves, drops, sales and deposits. Crafting can use locked materials.')}<div class="inventory-detail">${detail}</div>`,'inventory-pack')}</div>${storageMode?'':!bank?section('Universal Storage',note('Remote chest view is locked until a later world. Walk to a chest in either town.')+btn('FIND CHEST','data-find-storage=""')):section('Universal Storage',`<div class="inventory-toolbar"><strong>${E.chestUsed(s)} / ${E.chestCapacity(s)} chest slots</strong>${btn('DEPOSIT ALL','data-deposit-all=""',!bank)}</div>${note(bank?'Every town chest shares these items. 999 materials per stack.':'Read-only away from a town chest. Walk to a chest to deposit or withdraw.')}${cells(chest,'chest',chestPage)}`,'inventory-bank')}<details class="inventory-overflow"><summary>Pending overflow · ${fmt(Object.values(c.overflow).reduce((a,b)=>a+b,0))}</summary>${note(Object.entries(c.overflow).filter(([,n])=>n).map(([id,n])=>esc(D.ITEMS[id]?.name)+': '+fmt(n)).join(' · ')||'Nothing waiting.')}${btn('CLAIM WHAT FITS','data-reclaim=""')}</details>`;
}
function itemDetail(s,c,id,gear=null){const d=D.ITEMS[id];return`<div class="item-heading">${itemArt(id)}<div><h3>${esc(d.name)}</h3><small class="rarity-text-${d.rarity}">${d.rarity.toUpperCase()} · ${gear?D.GEAR_SLOTS[D.EQUIPMENT[id].slot]:E.CARRY_TYPES[E.carryType(id)]}</small></div></div>${gear?`<p class="item-stat-line">${statText(E.equipmentStats(gear))}</p><p class="small">Stone slots ${gear.upgrades?.length||0}/3 · Rune slots ${gear.runes.length}/2 · Infusion: ${gear.infusion?D.ITEMS[gear.infusion].name:'empty'}</p>${c.loadout[D.EQUIPMENT[id].slot]?.uid!==gear.uid?`<p class="small">Compared with equipped: ${statText(Object.fromEntries(Object.entries(E.equipmentStats(gear)).map(([k,v])=>[k,v-(E.equipmentStats(c.loadout[D.EQUIPMENT[id].slot])[k]||0)])))}</p>`:''}`:`<p class="small">${D.purposes(id).map(esc).join(' · ')}</p>`}<button class="text-button" data-codex-item="${id}">SOURCES & USES ↗</button>`;}
const talentIcons={power:'sword',vitality:'shield',industry:'axe',precision:'eye',haste:'boot',signature:'star',primary:'attack',secondary:'sword',utility:'potion',force:'sword',fortitude:'shield',specialist:'pick',fortune:'coin',efficiency:'pick',prosperity:'leaf',mastery:'book',workmanship:'gear'};
export function talents(s,c,view={}){const tab=view.tab==='class'&&!c.class?'beginner':view.tab||'beginner',defs=tab==='class'?D.CLASS_TALENTS:tab==='profession'?D.PROF_TALENTS:D.TALENTS,bag=tab==='class'?c.classTalents:tab==='profession'?c.profTalents:c.talents,points=tab==='class'?E.classPoints(c):tab==='profession'?E.professionPoints(c):E.talentPoints(c),selected=defs[view.selected]?view.selected:Object.keys(defs)[0],d=defs[selected],n=bag[selected]||0,ability=abilitySet(c),locked=c.level<(d.level||1),attrs=tab==='class'?'data-class-talent':tab==='profession'?'data-prof-talent':'data-talent';return`<div class="talent-head">${portrait(c)}<div><h3>${c.class?D.CLASSES[c.class].name:'Beginner'} · Lv ${c.level}</h3><strong>${points} POINTS AVAILABLE</strong><p>Each talent page has its own point budget.</p></div></div>${tabs([['beginner','BEGINNER'],...(c.class?[['class',D.CLASSES[c.class].name.toUpperCase()]]:[]),['profession','PROFESSIONS']],tab,'data-talents-tab')}<div class="master-detail talent-layout"><div>${section('Talents',`<div class="talent-icon-grid">${Object.entries(defs).map(([id,d])=>`<button class="talent-icon ${id===selected?'selected':''} ${c.level<(d.level||1)?'talent-locked':''}" data-select-talent="${id}" aria-label="${d.name}, level ${bag[id]||0}">${icon(talentIcons[id])}<span>${bag[id]||0}</span>${points&&(bag[id]||0)<d.max&&c.level>=(d.level||1)?'<b>+</b>':''}</button>`).join('')}</div><p class="tree-name">${tab==='class'?D.CLASSES[c.class].name:tab==='profession'?'World One Professions':'Beginner'}</p>`)}${section('Point allocation',`<div class="spend-buttons">${[1,5,10,100].map(n=>btn(n===100?'MAX':String(n),`data-talent-count="${n}" class="${view.count===n?'primary':''}"`)).join('')}</div>${note('Select a talent, then invest points. Your build is saved automatically.')}`)}</div>${section('Selected Talent',`<div class="selected-talent">${icon(talentIcons[selected])}<h3>${d.name}</h3><strong>LEVEL ${n} / ${d.max}</strong><p>${d.description}</p><p class="small">${locked?'Unlocks at character level '+d.level:n>=d.max?'Maximum level reached.':`${Math.min(view.count||1,points,d.max-n)} point(s) will be invested.`}</p>${btn(locked?'LEVEL '+d.level+' REQUIRED':n>=d.max?'MAXED':'INVEST POINTS',`${attrs}="${selected}" class="primary"`,locked||!points||n>=d.max)}</div>${note(tab==='profession'?'Profession levels earn profession points.':'Earn three points per character level after level one.')}`,'talent-detail')}</div>${section('Attack Bar',`<div class="ability-cards">${ability.map((a,i)=>a?`<article><div class="item-heading">${icon(i===2?'shield':i===1?'star':'attack')}<h3>${a.name}</h3></div><p>${a.description}</p><small>${[4,8,12][i]} MP · ${a.cooldown}s cooldown · ${abilityAvailable(c,i)?'LEARNED':'LEVEL '+(i===1?6:10)+' + CLASS TALENT'}</small><div class="spend-buttons">${[0,1,2].map(slot=>btn((c.hotbar[slot]===i?'✓ ':'')+(slot+1),`data-assign-ability="${i}" data-slot="${slot}"`,!abilityAvailable(c,i))).join('')}</div></article>`:'').join('')}</div>`)}${section('Talent Presets',`<div class="preset-row">${c.builds.map((b,i)=>`<div><h4>PRESET ${i+1}</h4>${btn('SAVE CURRENT',`data-save-build="${i}"`)}${btn(b?'LOAD':'EMPTY',`data-load-build="${i}"`,!b||!['town','jungle-town'].includes(c.area))}</div>`).join('')}</div>${note('Save all three talent pages and attack-bar assignments. Load in either town. Reset potions are crafted from five shop fragments.')}${btn('USE RESET POTION · '+(c.bag['reset-potion']||0),'data-reset-build=""',!c.bag['reset-potion']||!['town','jungle-town'].includes(c.area))}`)}`;}
export const CODEX_TABS=[['quick','QUICK REF'],['quests','QUESTS'],['cards','CARDS'],['bestiary','BESTIARY'],['items','ITEMS'],['stars','STARS'],['achievements','ACHIEVEMENTS'],['tasks','TASKS']];
export function codexNav(active){return tabs(CODEX_TABS,active,'data-codex-tab');}
export function quickRef(s,c){const entries=[['inventory','chest','STORAGE','Shared chest · visit a town chest'],['industry','gear','ANVIL','Claim passive products at the anvil'],['industry','ore','FURNACES','Inputs and bars · town access'],['craft','sword','CRAFTING','World One recipes and blueprints'],['stamps','stamp','STAMPS','Permanent account upgrades'],['statues','statue','STATUES','Personal character bonuses'],['vault','chest','UPGRADE VAULT','Spend coins on roster upgrades'],['stars','star','STAR SIGNS','Telescope and constellation chart'],['tasks','flag','TASKS & MERITS','World and daily challenges'],['trial','attack','SOLO TRIALS','Timed waves and score rewards'],['gems','gem','GEM WARDROBE','Earned cosmetics · no purchases'],['town','map','TOWN SERVICES','Shops, alchemy and enchanting']];return`<div class="codex-banner"><div>${icon('book')}<h3>World One Reference</h3></div><p>Everything your roster has learned, in one place.</p></div><div class="quick-grid">${entries.map(([panel,art,title,text])=>`<button ${panel==='industry'?'data-open-industry="'+(art==='ore'?'furnaces':'produce')+'"':'data-panel="'+panel+'"'}>${icon(art)}<strong>${title}</strong><small>${text}</small></button>`).join('')}</div>${note('Remote reference does not bypass town access. Chest transfers, shop purchases, furnace inputs, stamps and statues still require visiting their facilities.')}`;}
export function journal(s,c,v={}){const obtained=D.STORY.filter(q=>s.story[q.id]?.accepted||s.story[q.id]?.done),filter=v.questFilter||'active',list=obtained.filter(q=>filter==='all'||(filter==='done')===!!s.story[q.id]?.done),q=list.find(q=>q.id===v.quest)||list[0],st=q?E.questStatus(s,q.id):null;return`<div class="inventory-topline"><strong>WORLD ONE TOKENS ${s.npcTokens.length}/6</strong>${s.worldCompletionCrafted?'<b>COMPLETION TOKEN FORGED</b>':''}</div>${tabs([['active','IN PROGRESS'],['done','COMPLETED'],['all','ALL OBTAINED']],filter,'data-quest-filter')}<div class="master-detail">${section('Quest Journal',`<div class="ledger-list">${list.map(q=>btn(`<strong>${q.name}</strong><small>${q.giver==='steward'?'Hesta':D.CLASSES[q.giver].trainer} · ${s.story[q.id].done?'COMPLETE':E.questStatus(s,q.id).ready?'READY TO TURN IN':'IN PROGRESS'}</small>`,`data-select-quest="${q.id}" class="${q.id===st?.q.id?'selected':''}"`)).join('')||note('No quests here. Speak to NPCs to obtain quests; unaccepted quests stay out of this journal.')}</div>`)}${section('Quest Details',st?`<h3>${q.name}</h3><p>${q.text}</p><ul class="objective-list">${st.tasks.map(t=>`<li class="${t.done?'quest-complete':''}">${t.done?'✓':'○'} ${t.text} <strong>${fmt(t.have)}/${t.need}</strong></li>`).join('')}</ul><p class="reward-line">${q.reward.coins||0} coins${q.reward.items?' · '+Object.entries(q.reward.items).map(([id,n])=>`${n} ${D.ITEMS[id].name}`).join(''):''}${q.reward.recipes?.length?' · '+q.reward.recipes.map(id=>id+' blueprints').join(', '):''}</p><div class="save-actions">${!st.done?btn(s.trackedQuest===q.id?'✓ TRACKED':'TRACK QUEST',`data-track="${q.id}"`)+btn('VISIT QUEST GIVER',`data-find-npc="${q.giver}"`):'<strong>QUEST COMPLETED</strong>'}</div>`:note('Select an obtained quest to see its objectives and rewards.'))}</div>${section('Class Initiations',`<div class="mentor-list">${c.metMentors.map(id=>{const q=E.classQuest(s,c,id),d=D.CLASSES[id];return`<article>${portrait({class:id})}<div><h4>${d.trainer} · ${d.name}</h4><p>${c.class?(c.class===id?'Your class':'For another character'):q.text}</p><small>Step ${Math.min(3,q.stage+1)}/3 · ${D.SKILLS[d.skill]} specialist</small></div>${btn('VISIT',`data-find-npc="${id}"`)}</article>`;}).join('')||note('Speak with class mentors to add their initiations here.')}</div>`)}${section('NPC Tokens',`<div class="token-row">${D.NPC_TOKEN_GIVERS.map(id=>`<div class="${s.npcTokens.includes(id)?'earned':''}">${itemArt('world-token-'+id)}<span>${id==='steward'?'Hesta':D.CLASSES[id].trainer}</span><small>${D.STORY.filter(q=>q.giver===id&&s.story[q.id]?.done).length}/3 quests</small></div>`).join('')}</div>${note('Finish every quest from a giver for their one-time token. Combine all six at the anvil.')}`)}`;}
export function cards(s,c,v={}){const group=v.cardGroup||'all',groups=[['all','ALL'],...Object.entries(D.CARD_COLLECTIONS).map(([id,d])=>[id,d.name.toUpperCase()])],list=Object.entries(D.CARDS).filter(([id])=>group==='all'||D.CARD_COLLECTIONS[group].ids.includes(id)),id=list.some(([id])=>id===v.card)?v.card:list[0]?.[0],d=D.CARDS[id],rank=E.cardRank(s,id),active=c.cardSets[c.cardPreset].includes(id);return`<div class="inventory-topline"><strong>${c.cardSets[c.cardPreset].length}/${E.cardSlots(s)} EQUIPPED · ${Object.keys(s.cards).length}/${Object.keys(D.CARDS).length} FOUND</strong>${tabs([['combat','COMBAT'],['skilling','SKILLING']],c.cardPreset,'data-card-preset')}</div><div class="equipped-cards">${Array.from({length:E.cardSlots(s)},(_,i)=>{const id=c.cardSets[c.cardPreset][i];return id?btn(icon(D.CARDS[id].kind==='resource'?'pick':'cards')+`<small>${D.CARDS[id].name.replace(' Card','')}</small>`,`data-card="${id}" title="Unequip ${D.CARDS[id].name}"`):'<div>'+icon('cards','#897c65')+'<small>EMPTY</small></div>';}).join('')}</div>${tabs(groups,group,'data-card-group')}<div class="master-detail">${section('Collection',`<div class="card-album">${list.map(([id,d])=>`<button data-select-card="${id}" class="${E.cardRank(s,id)?'':'undiscovered'} ${v.card===id?'selected':''}">${icon(d.kind==='resource'?'pick':'cards',D.ENEMIES[id]?.area==='deep'?'#b29ac8':'#e4c079')}<span>${d.name.replace(' Card','')}</span><strong>${'★'.repeat(E.cardRank(s,id))||'—'}</strong></button>`).join('')}</div>`)}${section('Card Details',d?`<div class="selected-card">${icon(d.kind==='resource'?'pick':'cards')}<h3>${d.name}</h3><strong>${rank?'★'.repeat(rank):'NOT FOUND'}</strong><p>${fmt(s.cards[id])} copies · Next rank ${[1,10,30,100,300][rank]||'MAX'}</p><h4>+${percent(d.amount*Math.max(1,rank))} ${d.effect}</h4><p>${d.kind==='monster'?'Drops from '+D.ENEMIES[id].name+' · 2.5%':'Drops while gathering '+D.ITEMS[id].name+' · 1.5% per resource'}</p>${btn(active?'UNEQUIP':'EQUIP CARD',`data-card="${id}" class="primary"`,!rank||!active&&c.cardSets[c.cardPreset].length>=E.cardSlots(s))}</div>`:'')}</div>${section('Card Set Bonus',`<div class="set-bonuses">${Object.entries(D.CARD_COLLECTIONS).map(([id,d])=>{const tier=E.cardCollectionTier(s,id),selected=c.cardSetBonuses[c.cardPreset]===id;return`<article><strong>${d.name}</strong><p>Rank ${tier}/3 · +${percent(d.amount*tier)} ${d.effect}</p><small>Every 3 combined card ranks raises the set by one tier.</small>${btn(selected?'✓ ACTIVE':'ACTIVATE',`data-card-collection="${id}"`,!tier)}</article>`;}).join('')}</div>`)}${note('Collection copies are shared. Equipped cards, chosen set bonuses and combat/skilling presets belong to each character.')}`;}
export function crafting(s,c,near,v={}){const station=near?E.stationFor(c):null,filter=v.stationOnly||v.recipeFilter||station||'all',list=D.RECIPES.filter(r=>!r.retired&&(!v.recipePage||E.recipePage(r)===Number(v.recipePage))&&(filter==='all'||filter==='favorites'?filter!=='favorites'||s.recipeFavorites.includes(r.id):r.station===filter)&&(!v.recipeSearch||r.name.toLowerCase().includes(v.recipeSearch.toLowerCase()))),r=list.find(r=>r.id===v.recipe)||list[0];return`<div class="inventory-topline"><strong>${station?'AT '+station.toUpperCase():'RECIPE REFERENCE'}</strong>${v.stationOnly?'':btn('PRODUCE / FURNACES','data-panel="industry"')}</div>${v.stationOnly?'':tabs([['all','ALL'],['anvil','ANVIL'],['foundry','FORGE'],['enchanting','ENCHANT'],['alchemy','ALCHEMY'],['favorites','FAVORITES']],filter,'data-recipe-filter')}<label class="search-field">${icon('eye')}<input id="recipe-search" aria-label="Find a recipe" placeholder="Find a recipe" value="${esc(v.recipeSearch||'')}" autocomplete="off"></label><div class="master-detail">${section('Recipes',`<div class="recipe-icon-grid">${list.map(r=>`<button data-select-recipe="${r.id}" class="${r.id===v.recipe?'selected':''} ${E.recipeOpen(s,r)?'':'recipe-locked'}" title="${E.recipeOpen(s,r)?r.name:'Locked blueprint'}">${E.recipeOpen(s,r)?itemArt(r.equipment||r.output||'dust'):'<strong class="recipe-question">?</strong>'}<span>${E.recipeOpen(s,r)?r.name:'Locked recipe · page '+E.recipePage(r)}</span>${s.recipeFavorites.includes(r.id)?'<b>★</b>':''}</button>`).join('')||note('No matching recipes.')}</div>`)}${section('Crafting Details',r?`<div class="item-heading">${itemArt(r.equipment||r.output||'dust')}<h3>${r.name}</h3></div><p>${r.equipment?statText(D.EQUIPMENT[r.equipment].stats):r.output?`Produces ${r.count} ${D.ITEMS[r.output].name}${c.class&&D.CLASSES[c.class].skill===r.skill?' · specialist double yield':''}`:'Permanent character improvement'}</p><p class="recipe-status">${!E.recipeOpen(s,r)?'BLUEPRINT LOCKED · '+E.blueprintHint(s,r):station!==r.station?'VISIT THE '+r.station.toUpperCase():'STATION READY'}</p><div class="ingredient-list">${Object.entries(E.craftCost(c,r)).map(([id,n])=>`<button data-codex-item="${id}">${itemArt(id)}<span>${D.ITEMS[id].name}<small>${fmt(E.amount(s,id,c))}/${n} available</small></span><b class="${E.canPay(s,{[id]:n},c)?'can-pay':'cannot-pay'}">${n}</b></button>`).join('')}</div><p>${E.money(E.craftFee(c,r))} per craft${r.duration?' · '+r.duration+'s per batch':''}</p><div class="save-actions">${btn(r.station==='foundry'?'QUEUE 1':'CRAFT',`data-craft="${r.id}" class="primary"`,!E.canCraft(s,c,r)||station!==r.station)}${r.station==='foundry'?[5,10].map(n=>btn('QUEUE '+n,`data-queue="${r.id}" data-count="${n}"`,station!=='foundry'||!E.recipeOpen(s,r)||s.jobs.length>=E.queueSlots(s)||!E.canPay(s,E.queueCost(r,n),c)||s.coins<n*2)).join(''):''}${E.OPTIONAL_BLUEPRINTS.includes(r.id)&&!s.workshop.blueprints.includes(r.id)?btn('LEARN · 1 BLUEPRINT TOKEN',`data-learn-blueprint="${r.id}"`,station!=='anvil'||s.workshop.tokens<1):''}${btn(s.recipeFavorites.includes(r.id)?'★ FAVORITE':'☆ FAVORITE',`data-recipe-favorite="${r.id}"`)}</div>${station!==r.station?btn('FIND STATION',`data-find-station="${r.station}"`):''}`:note('Select a recipe.'))}</div>${s.jobs.length?section('Active Forge Queue',`<div class="job-list">${s.jobs.map(j=>`<div><strong>${D.RECIPES.find(r=>r.id===j.recipe).name}</strong><span>${j.remaining} batches · ${Math.ceil(E.jobDuration(s,j)-j.progress)}s</span>${btn('CANCEL',`data-cancel-job="${j.id}"`)}</div>`).join('')}</div>`):''}`;}
export function bestiary(s,c,v={}){const list=Object.values(D.ENEMIES).filter(e=>!v.enemyArea||v.enemyArea==='all'||e.area===v.enemyArea),e=list.find(e=>e.id===v.enemy)||list[0];return`${tabs([['all','ALL'],['forest','FOREST'],['caves','CAVES'],['jungle','JUNGLE'],['deep','DEPTHS'],['tree','ELDER TREE']],v.enemyArea||'all','data-enemy-area')}<div class="master-detail">${section('Creatures',`<div class="ledger-list">${list.map(e=>btn(`<strong>${e.name}</strong><small>${fmt(s.kills[e.id])} defeated · ${E.cardRank(s,e.id)?'Card collected':'No card yet'}</small>`,`data-select-enemy="${e.id}" class="${e.id===v.enemy?'selected':''}"`)).join('')}</div>`)}${section('Creature Details',e?`<div class="bestiary-portrait">${icon(e.shape==='stump'?'leaf':e.shape==='golem'?'shield':e.shape==='moth'||e.shape==='bat'?'star':'eye')}<h3>${e.name}</h3></div><div class="sheet-stats">${mini('HP',fmt(e.hp))}${mini('Attack',e.attack)}${mini('XP / kill',e.xp)}${mini('Base coins',E.money(e.coins))}${mini('Your hit chance',percent(E.hitChance(c,e)))}${mini('Guaranteed hit accuracy',E.enemyAccuracy(e))}</div><p class="ui-note">${e.behavior==='bolt'?'Ranged attacks: watch for projectiles.':e.behavior==='charge'?'Charges forward after winding up.':e.behavior==='guard'?'Periodically guards against incoming damage.':e.id==='boss'?'Boss phases summon rootlings and launch root waves.':'Close-range attacks have a visible windup.'}</p><h4>Enemy Drops</h4>${s.kills[e.id]?`<div class="drop-table">${e.loot.map(d=>`<button data-codex-item="${d.id}">${itemArt(d.id)}<span>${D.ITEMS[d.id].name}</span><b>${d.chance<.001?d.chance*100+'%':percent(d.chance)}</b></button>`).join('')}</div><details><summary>World and global drops</summary><div class="drop-table">${[...D.WORLD_LOOT,...D.GLOBAL_LOOT].map(d=>`<button data-codex-item="${d.id}">${itemArt(d.id)}<span>${D.ITEMS[d.id].name}</span><b>${(d.chance*100).toPrecision(2)}%</b></button>`).join('')}</div></details>`:note('Defeat this creature once to reveal its loot table.')}<button data-select-card="${e.id}" data-open-card="">VIEW CARD ↗</button>`:'')}</div>`;}
export function itemIndex(s,c,v={}){const list=Object.keys(D.ITEMS).filter(id=>!v.itemSearch||D.ITEMS[id].name.toLowerCase().includes(v.itemSearch.toLowerCase())),id=list.includes(v.item)?v.item:list[0],d=D.ITEMS[id];return`<label class="search-field">${icon('eye')}<input id="item-search" aria-label="Find an item" placeholder="Find an item" autocomplete="off" value="${esc(v.itemSearch||'')}"></label><div class="master-detail">${section('World One Items',`<div class="item-index-grid">${list.map(id=>`<button data-select-item="${id}" title="${esc(D.ITEMS[id].name)}" class="${id===v.item?'selected':''}">${itemArt(id)}<span>${D.ITEMS[id].name}</span></button>`).join('')}</div>`)}${section('Item Reference',d?`<div class="item-heading">${itemArt(id)}<div><h3>${d.name}</h3><small>${d.rarity.toUpperCase()}</small></div></div>${D.EQUIPMENT[id]?'<p>'+statText(D.EQUIPMENT[id].stats)+'</p>':''}<p>${fmt(c.bag[id]||0)} carried · ${E.storageAccess(c)?fmt(s.inventory[id]||0):'Remote view locked'} in storage</p><h4>Sources</h4><div class="source-list">${sources(id).map(x=>`<div>${x.recipe?btn(x.text,`data-open-recipe="${x.recipe}"`):x.enemy?btn(x.text,`data-select-enemy="${x.enemy}" data-open-enemy=""`):esc(x.text)}</div>`).join('')||note('Earned through World One exploration and progression.')}</div><h4>Uses</h4><ul class="objective-list">${D.purposes(id).map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><div class="save-actions">${(E.BADGES[id]?['attune','pattern']:['reclaim','project',...(E.INFUSION_ITEMS().includes(id)?['infusion']:[])]).map(use=>btn({attune:'TOKEN ATTUNEMENT',pattern:'SIGNATURE PATTERN',reclaim:'FOUNDRY RECLAMATION',project:'TOWN PROJECT',infusion:'RELIC INFUSION'}[use],`data-economy-use="${use}" data-item="${id}"`)).join('')}</div>`:note('No items match.'))}</div>`;}
export function stars(s,c,v={}){const selected=D.STAR_SIGNS[v.sign]?v.sign:'sprout',d=D.STAR_SIGNS[selected],tab=v.starTab||'chart';if(!s.stars.unlocked)return`<div class="unlock-card">${icon('star')}<h3>A sky above the canopy</h3><p>Climb the Elder Tree’s three zones: Rootspire Ascent, Heartwood Stair and Crown Observatory. Find the telescope on the highest platform of the third zone to unlock star signs.</p>${btn('FIND THE ELDER TREE','data-reveal-room="forest:4"')}<small>Enter the tree from the upper platform in The Elder’s Roots. There is no summit shortcut until you reach the telescope.</small></div>`;return`<div class="inventory-topline"><strong>${E.starPoints(s)} STAR POINTS</strong><span>${s.stars.claimed.length}/8 constellations · ${c.starSigns.length}/${E.starSlots(s)} signs equipped</span></div>${tabs([['chart','STAR CHART'],['constellations','CONSTELLATIONS']],tab,'data-star-tab')}${tab==='chart'?`<div class="master-detail">${section('The Greenreach Sky',`<div class="star-chart">${Object.entries(D.STAR_SIGNS).map(([id,d])=>`<button data-select-sign="${id}" class="${s.stars.signs.includes(id)?'unlocked':''} ${c.starSigns.includes(id)?'equipped':''} ${selected===id?'selected':''}">${icon(d.icon)}<strong>${d.name}</strong><small>${c.starSigns.includes(id)?'EQUIPPED':s.stars.signs.includes(id)?'UNLOCKED':d.cost+' POINTS'}</small></button>`).join('')}</div>`)}${section('Star Sign',`<div class="selected-talent">${icon(d.icon)}<h3>${d.name}</h3><p>${d.text}</p><small>${d.requires.length?'Requires '+d.requires.map(id=>D.STAR_SIGNS[id].name).join(', '):'A beginning in the night sky.'}</small>${s.stars.signs.includes(selected)?btn(c.starSigns.includes(selected)?'UNEQUIP':'EQUIP SIGN',`data-equip-sign="${selected}"`,!c.starSigns.includes(selected)&&c.starSigns.length>=E.starSlots(s)):btn('UNLOCK · '+d.cost+' POINTS',`data-unlock-sign="${selected}"`,E.starPoints(s)<d.cost||d.requires.some(id=>!s.stars.signs.includes(id)))}</div>${note('Unlocks are shared; equipped signs are personal. Complete four constellations for a second slot, and all eight for a third.')}`)}</div>`:`<div class="constellation-list">${D.CONSTELLATIONS.map(d=>{const done=s.stars.claimed.includes(d.id),seen=s.stars.seen.includes(d.id),n=E.constellationValue(s,c,d);return`<article class="ledger-box"><div class="item-heading">${icon('star',done?'#efce78':'#a6bfc9')}<div><h3>${d.name}</h3><small>${d.secret?D.SECRETS[d.secret].name:roomLayout(d.area,d.zone).title}</small></div></div><p>${d.text}</p><p>${done?'COMPLETE · +2 STAR POINTS':(seen?'OBSERVED':'NOT YET OBSERVED')+' · '+Math.min(n,d.goal)+'/'+d.goal}</p>${btn('SHOW ON MAP',`data-reveal-room="${d.area}:${d.zone}"`)}</article>`;}).join('')}</div>${note('Find and interact with the constellation in its room. Return to its marker after meeting the requirement to complete it. Requirements involving skill or character levels use your controlled character.')}`}`;}
export function vault(s){return`<div class="codex-banner"><div>${icon('chest')}<h3>The Greenreach Vault</h3></div><p>Permanent upgrades for every character · ${E.money(s.coins)}</p></div><div class="vault-grid">${Object.entries(D.VAULT_UPGRADES).map(([id,d])=>{const n=s.vault[id]||0,cost=E.vaultCost(s,id);return`<article class="ledger-box"><div class="item-heading">${icon({edge:'sword',ward:'shield',heart:'food',ore:'pick',wood:'axe',patience:'hourglass',packs:'bag',mint:'coin'}[id])}<div><h3>${d.name}</h3><small>LEVEL ${n}/${d.max}</small></div></div><p>${d.text}</p><progress value="${n}" max="${d.max}"></progress>${btn(n>=d.max?'MAXED':'UPGRADE · '+E.money(cost),`data-vault-upgrade="${id}"`,n>=d.max||s.coins<cost)}</article>`;}).join('')}</div>${note('Coin costs increase with each level. Vault bonuses are separate from stamps, personal statues and equipped star signs.')}`;}
export function achievements(s){return`<div class="inventory-topline"><strong>${s.achievementClaims.length}/${D.ACHIEVEMENTS.length} CLAIMED</strong><span>One-time World One goals · earned gems</span></div><div class="achievement-grid">${D.ACHIEVEMENTS.map(d=>{const n=E.achievementValue(s,d),done=s.achievementClaims.includes(d.id);return`<article class="ledger-box ${done?'achievement-claimed':''}"><div class="item-heading">${icon('trophy')}<h3>${d.name}</h3></div><p>${d.text}</p><progress value="${Math.min(n,d.goal)}" max="${d.goal}"></progress><p>${Math.min(n,d.goal)}/${d.goal} · ${d.gems} gems</p>${btn(done?'CLAIMED':'CLAIM REWARD',`data-achievement="${d.id}"`,done||n<d.goal)}</article>`;}).join('')}</div>`;}
export function trials(s,c){E.refreshTrials(s);return`<div class="trial-banner">${icon('attack')}<div><h3>Greenreach Solo Trials</h3><p>Eight waves. Three minutes. One character.</p></div></div><div class="offline-grid"><div>${s.trials.tickets}<small>TICKETS · +3 DAILY, CAP 6</small></div><div>${s.trials.best}<small>PERSONAL BEST</small></div><div>${s.trials.runs}<small>RUNS FINISHED</small></div></div><p>Each defeated enemy scores 5 × the wave number. The run ends when the timer expires, your character falls or all eight waves are cleared. Earn 2 coins per point. Bronze (100), silver (250) and gold (500) award one-time gems.</p><div class="trial-medals">${[100,250,500].map((n,i)=>`<div class="${s.trials.medals.includes(n)?'earned':''}">${icon('trophy',['#bc9163','#c1cbd0','#e7c567'][i])}<strong>${['BRONZE','SILVER','GOLD'][i]}</strong><small>${n} POINTS</small></div>`).join('')}</div><div class="save-actions">${btn('ENTER TRIAL · 1 TICKET','data-start-trial="" class="primary"',!E.nearFacility(c,'arena')||c.level<3||!s.trials.tickets)}${btn('FIND TRIAL BOARD','data-find-facility="arena"')}</div>${note('Enter at the board in Legacy Square. Requires level 3. Trials are active play only; closing or reloading the game ends an attempt without granting its unclaimed score. Normal enemy drops are disabled in the trial.')}`;}
const atlasPositions={town:[[100,530],[240,530],[380,530],[100,650]],forest:[[100,380],[240,380],[380,380],[520,380],[660,380]],caves:[[520,530],[660,530],[800,530]],jungle:[[660,250],[520,250],[380,250],[240,250]],deep:[[800,650],[660,650],[520,650],[380,650]],'jungle-town':[[240,120],[380,120],[520,120]],tree:[[840,320],[840,220],[840,120]]};
export function map(s,c,v={}){E.refreshTeleports(s);const selected=v.mapRoom||`${c.area}:${c.zone}`,[area,z]=selected.split(':'),zone=Number(z),a=D.areaById(area)||D.AREAS[0],index=Number.isInteger(zone)&&zone<a.zones.length?zone:0,e=D.zoneEnemy(a.id,index),current=c.area===a.id&&c.zone===index&&!c.secret&&!c.trial&&c.activity!=='boss',seen=E.discovered(s,a.id,index),open=E.zoneUnlocked(s,a.id,index),nodes=D.AREAS.flatMap(a=>a.zones.map((name,i)=>({area:a.id,zone:i,name:roomLayout(a.id,i).title,p:atlasPositions[a.id][i]}))),edges=new Map();for(const n of nodes)for(const p of roomPortals(n.area,n.zone)){if(p.destination.boss)continue;const other=nodes.find(x=>x.area===p.destination.area&&x.zone===p.destination.zone);if(!other)continue;const key=[n.area+n.zone,other.area+other.zone].sort().join('/');if(!edges.has(key))edges.set(key,[n.p,other.p]);}return`<div class="inventory-topline"><strong>WORLD ONE · THE GREENREACH</strong><span>${s.teleports.count}/30 teleports · +3 each day</span></div><div class="map-layout"><div class="atlas-scroll"><div class="world-atlas"><svg viewBox="0 0 940 730" aria-hidden="true">${[...edges.values()].map(([a,b])=>`<path d="M${a[0]} ${a[1]} L${b[0]} ${b[1]}"/>`).join('')}</svg>${nodes.map(n=>{const seen=E.discovered(s,n.area,n.zone),here=c.area===n.area&&c.zone===n.zone;return`<button class="atlas-node ${seen?'discovered':''} ${here?'current':''} ${selected===n.area+':'+n.zone?'selected':''}" style="left:${n.p[0]}px;top:${n.p[1]}px" data-map-room="${n.area}:${n.zone}" aria-label="${n.name}${seen?', discovered':', undiscovered'}">${icon(['town','jungle-town'].includes(n.area)?'chest':n.area==='tree'?'leaf':n.area==='caves'||n.area==='deep'?'ore':'leaf')}<small>${n.name}</small>${here?'<b>YOU</b>':''}</button>`;}).join('')}<span class="atlas-label" style="left:10px;top:300px">FOREST</span><span class="atlas-label" style="left:15px;top:460px">HEARTHSTEAD</span><span class="atlas-label" style="left:445px;top:580px">DEEP CAVERNS</span><span class="atlas-label" style="left:650px;top:180px">ELDER TREE ↑</span><span class="atlas-label" style="left:50px;top:180px">VERDANT OUTPOST</span></div></div>${section('Selected Room',`<h3>${esc(roomLayout(a.id,index).title)}</h3><p>${a.name} · ${index+1}/${a.zones.length}</p><strong class="recipe-status">${current?'YOU ARE HERE':!open?'ROUTE LOCKED':seen?'DISCOVERED':'WALK HERE TO DISCOVER'}</strong>${!open?'<p>'+E.lockReason(s,a.id,index)+'</p>':''}${e?`<div class="sheet-stats">${mini('Enemy',e.name)}${mini('Health',e.hp)}${mini('Accuracy needed',E.enemyAccuracy(e))}${mini('Your hit chance',percent(E.hitChance(c,e)))}${mini('Kills',fmt(s.kills[e.id]))}${mini('Next route',Math.min(12,s.kills[e.id]||0)+'/12')}</div>`:'<p>Town services and universal storage.</p>'}<div class="map-resources">${a.resources[index].map(id=>itemArt(id)+'<span>'+D.ITEMS[id].name+'</span>').join('')}</div>${a.id==='tree'?note('A tall room with '+(10+index*2)+' elevated platforms. Tap the room overview to climb.'):''}<div class="save-actions">${btn(current?'CURRENT ROOM':'TELEPORT · 1',`data-travel="${a.id}" data-zone="${index}"`,!current&&(!open||!seen||!s.teleports.count))}${e?btn('CREATURE INFO',`data-select-enemy="${e.id}" data-open-enemy=""`):''}</div>${btn('BOTTLED TOWN RETURN · '+(c.bag['town-teleport']||0),'data-town-return="town"',!c.bag['town-teleport'])}${note('Portals cost no charges. Map teleports only reach rooms you have discovered. The summit lift stays locked until the telescope is reached.')}`,'atlas-detail')}</div>`;}
export function roster(s){return`<div class="inventory-topline"><strong>YOUR ADVENTURERS</strong><span>${s.characters.length}/${E.slots(s)} character slots</span></div><div class="player-cards">${s.characters.map(c=>{const r=E.rates(s,c);return`<article class="player-card ledger-box">${portrait(c)}<h3>${esc(c.name)}</h3><strong>${c.class?D.CLASSES[c.class].name:'Beginner'} · Lv ${c.level}</strong><p>${roomLayout(c.area,c.zone).title}</p><div class="assignment-badge">${c.activity.toUpperCase()} · ${r.label}</div><div class="sheet-stats">${mini('XP / hour',fmt(r.xp))}${mini('Items / hour',fmt(r.items))}${mini('Backpack',E.bagUsed(c)+'/'+E.bagCapacity(c))}</div><div class="save-actions">${btn(s.active===c.id?'CONTROLLING':'PLAY',`data-character="${c.id}"`,s.active===c.id)}${btn('ASSIGN',`data-assignment="${c.id}"`)}</div></article>`;}).join('')}${Array.from({length:Math.max(0,E.slots(s)-s.characters.length)},()=>`<article class="player-card player-empty ledger-box">${icon('people')}<h3>A New Adventurer</h3><p>Choose a different class to grow your roster.</p>${btn('CREATE CHARACTER','data-panel="new"')}</article>`).join('')}</div>${note('Each first class discovery unlocks a slot. You need one of every class before choosing duplicates. Every character has a personal inventory, equipment, talents and assignments.')}`;}
export function options(s,audio){return`<div class="options-layout">${section('Display & Play',`<div class="option-list">${[['questHelper','Quest helper','Show your tracked quest in the world.'],['damageNumbers','Damage numbers','Show combat hits, misses and healing text.'],['autoPickup','Auto pickup','Pick up nearby floor loot automatically.'],['autoSkills','Auto skill use','Let AUTO use learned skills when mana permits.'],['reducedMotion','Reduced motion','Reduce decorative movement.'],['compact','Compact interface','Use tighter menu spacing.']].map(([id,name,desc])=>`<div><span><strong>${name}</strong><small>${desc}</small></span>${btn(s.options[id]?'ON':'OFF',`data-option="${id}" aria-pressed="${s.options[id]}"`)}</div>`).join('')}</div>`)}${section('Audio & Save',`<div class="save-actions">${btn(audio.enabled?'MUTE SOUNDS':'ENABLE SOUNDS','data-audio=""')}</div><label class="volume-control">Sound volume<input id="audio-volume" type="range" min="0" max="1" step="0.05" value="${audio.volume}"></label><div class="save-actions">${btn('EXPORT SAVE','data-export=""')}${btn('IMPORT SAVE','data-import=""')}</div>${note('Saved in this browser. Export backups to move between devices. Import asks before replacing the current roster.')}`)}</div>${section('Keyboard & Touch',`<div class="key-help">${[['I','Items'],['T','Talents'],['C','Codex'],['M','Map'],['P','Players'],['Q','Attacks'],['ESC','Menu / Close'],['1–3','Skills'],['A / D','Walk'],['W / S','Climb'],['SPACE','Jump'],['E','Interact']].map(([k,v])=>'<span><kbd>'+k+'</kbd>'+v+'</span>').join('')}</div>${note('Tap targets to walk over and interact. Inventory supports tap-to-move, splitting, dropping and locks; dragging is also available on PC.')}`)}`;}
export function menu(s,c){return`<div class="quick-grid menu-grid">${[['inventory','bag','ITEMS'],['skills','star','TALENTS'],['codex','book','CODEX'],['afk','hourglass','AFK INFO'],['roster','people','SWAP PLAYERS'],['craft','gear','PROFESSIONS'],['town','chest','TOWN SERVICES'],['settings','gear','OPTIONS & SAVE']].map(([id,art,title])=>`<button data-panel="${id}">${icon(art)}<strong>${title}</strong></button>`).join('')}</div>${section('World One Progress',`<div class="completion-row">${mini('Classes',s.unlockedClasses.length+'/5')}${mini('NPC Tokens',s.npcTokens.length+'/6')}${mini('Constellations',s.stars.claimed.length+'/8')}${mini('Rootwarden',s.bossDefeated?'DEFEATED':'ALIVE')}${mini('Completion token',s.worldCompletionCrafted?'FORGED':'NOT FORGED')}</div>`)}${note('Your own adventurers, sharing one World One journey.')}`;}
export function stamps(s,c,v={}){const group=v.stampGroup||'Combat',list=Object.entries(D.STAMPS).filter(([,d])=>d.group===group),id=list.some(([id])=>id===v.stamp)?v.stamp:list[0][0],d=D.STAMPS[id],st=s.stamps[id],cost=E.stampCost(s,id),near=E.nearFacility(c,'stamps');return`<div class="inventory-topline"><strong>STAMP REGISTRY · ${E.money(s.coins)}</strong>${btn('VISIT REGISTRY','data-find-facility="stamps"')}</div>${tabs([['Combat','COMBAT'],['Skills','SKILLS'],['Misc','MISC']],group,'data-stamp-group')}<div class="master-detail">${section('Stamp Collection',`<div class="stamp-grid">${list.map(([id,d])=>`<button data-select-stamp="${id}" class="${s.stamps[id]?'registered':''} ${v.stamp===id?'selected':''}">${itemArt('stamp-'+id)}<strong>${d.name}</strong><small>${s.stamps[id]?'LV '+s.stamps[id].level:'NOT REGISTERED'}</small></button>`).join('')}</div>`)}${section('Stamp Details',`<div class="item-heading">${itemArt('stamp-'+id)}<h3>${d.name}</h3></div><p>+${d.effect==='defense'?d.amount:percent(d.amount)} ${d.effect} per level · affects the roster</p><p>${st?'LEVEL '+st.level+' / CAP '+st.cap:'Find: '+d.source}</p>${!st?btn('REGISTER CARRIED STAMP',`data-town-action="register" data-id="${id}"`,!near||!c.bag['stamp-'+id]):st.level<st.cap?btn('UPGRADE · '+E.money(cost.coins),`data-town-action="stamp" data-id="${id}"`,!near||s.coins<cost.coins):`<p>Next cap costs ${cost.quantity} carried ${D.ITEMS[cost.material].name}. You carry ${fmt(c.bag[cost.material])}.</p>${btn('INCREASE CAP +5',`data-town-action="cap" data-id="${id}"`,!near||(c.bag[cost.material]||0)<cost.quantity)}`}${!near?note('Reference only here. Stand beside the Stamp Registry in Legacy Square to upgrade.'):''}`)}</div><details class="profession-details"><summary>Material research</summary>${Old.materialStudies(s)}</details>`;}
export function statues(s,c,v={}){const id=D.STATUES[v.statue]?v.statue:'power',d=D.STATUES[id],near=E.nearFacility(c,'statues'),points=c.statues[id]||0,next=E.statueNext(c,id),level=E.statueLevel(c,id);return`<div class="inventory-topline"><strong>${esc(c.name)}’S STATUES</strong>${btn('VISIT KEEPER','data-find-facility="statues"')}</div>${!c.statuesUnlocked?section('Personal Collection',note('Buy a Sculptor’s Chisel in Hearthstead, then bring it to the Statue Keeper to unlock this character’s deposits.')+btn('USE CARRIED CHISEL','data-town-action="unlock"',!near||!c.bag['sculpting-tool'])):''}<div class="master-detail">${section('Statues',`<div class="stamp-grid">${Object.entries(D.STATUES).map(([id,d])=>`<button data-select-statue="${id}" class="${v.statue===id?'selected':''}">${itemArt('statue-'+id)}<strong>${d.name}</strong><small>LV ${E.statueLevel(c,id)}</small></button>`).join('')}</div>`)}${section('Statue Details',`<div class="item-heading">${itemArt('statue-'+id)}<h3>${d.name}</h3></div><p>LEVEL ${level} · +${d.effect==='defense'?Number((d.amount*level).toFixed(2)):percent(d.amount*level)} ${d.effect}</p><progress value="${points}" max="${next}"></progress><p>${fmt(points)} deposited · ${fmt(next-points)} to next level</p><p>${E.unlockedAmount(c,'statue-'+id)} unlocked statues carried</p>${btn('DEPOSIT CARRIED STATUES',`data-town-action="statue" data-id="${id}"`,!near||!c.statuesUnlocked||!E.unlockedAmount(c,'statue-'+id))}${note('Find: '+d.source+'. Deposits belong to this character and protect locked inventory slots.')}`)}</div>`;}
export function shop(s,c,v={}){const d=D.TOWN_SHOPS[c.area];if(!d)return note('Visit a town shop.');const selected=d.stock.find(r=>r[0]===v.item)||d.stock[0],[id,price]=selected,stock=E.shopRemaining(s,c.area,id),remaining=Math.ceil((E.DAY-Date.now()%E.DAY)/60000),t=E.bagSlots(c)[v.sellIndex],gear=t?.uid?c.packGear.find(g=>g.uid===t.uid):null,sellId=gear?.base||t?.id,near=E.nearFacility(c,'shop');return`<div class="inventory-topline"><strong>${d.name}</strong><span>${E.money(s.coins)} · restock ${Math.floor(remaining/60)}h ${remaining%60}m</span></div><div class="shop-layout">${section('Shop Stock',`<div class="shop-stock-grid">${d.stock.map(([id,p])=>`<button data-shop-item="${id}" class="${v.item===id?'selected':''}">${itemArt(id)}<small>${D.ITEMS[id].name}</small><strong>${E.money(p)}</strong><span>${E.shopRemaining(s,c.area,id)} left</span></button>`).join('')}</div><div class="inventory-detail"><div class="item-heading">${itemArt(id)}<h3>${D.ITEMS[id].name}</h3></div><p>${D.purposes(id).map(esc).join(' · ')}</p><p>${stock} in stock · ${E.money(price)} each</p><div class="save-actions">${[1,5,10].map(n=>btn('BUY '+n,`data-shop-buy="${id}" data-count="${n}"`,!near||stock<n||s.coins<price*n||E.carryRoom(c,id)<n||id.startsWith('stamp-')&&s.stamps[id.slice(6)])).join('')}</div></div>`)}${section('Your Backpack',`<div class="shop-sell-grid">${E.bagSlots(c).map((t,i)=>{const gear=t?.uid?c.packGear.find(g=>g.uid===t.uid):null,id=gear?.base||t?.id;return t?`<button data-shop-select="${i}" class="${v.sellIndex===i?'selected':''}" ${c.lockedSlots.includes(i)?'disabled':''}>${itemArt(id)}<small>${D.ITEMS[id].name} ×${t.qty||1}</small><strong>${E.money(E.sellPrice(id))}</strong></button>`:'';}).join('')||note('Backpack empty.')}</div>${sellId?`<div class="inventory-detail"><h3>Sell ${D.ITEMS[sellId].name}</h3><label class="inventory-quantity">Quantity<input id="shop-sell-quantity" type="number" min="1" max="${t.qty||1}" value="${Math.min(v.quantity||1,t.qty||1)}"></label><p>${E.money(E.sellPrice(sellId))} per item</p>${btn(v.confirm?'CONFIRM SALE':'SELL SELECTED QUANTITY',`data-shop-sell="${v.sellIndex}" class="danger"`,!near||c.lockedSlots.includes(v.sellIndex))}</div>`:note('Select a carried stack to sell. Sales ask for confirmation. Locked items and completion tokens are protected.')}`)}</div>`;}
export function industry(s,c,near,v={}){const station=near?E.stationFor(c):null,tab=v.industryTab||'produce',a=c.anvil,used=Object.values(a.stored).reduce((x,y)=>x+y,0);let body='';if(tab==='produce')body=`<div class="inventory-topline"><strong>${esc(c.name)}’S ANVIL</strong><span>${used}/${E.anvilCapacity(s,c)} products · ${E.anvilPoints(c)} points</span></div><div class="product-grid">${Object.entries(D.ANVIL_PRODUCTS).map(([id,d])=>section(d.name,`${itemArt(id)}<strong>${a.stored[id]||0} STORED</strong><p>${(d.seconds/(1+a.upgrades.speed*.1)).toFixed(1)}s / product · ${(d.xp*(1+a.upgrades.xp*.05)).toFixed(1)} XP on claim</p><div class="save-actions">${btn(a.product===id?'✓ PRODUCING':'PRODUCE',`data-product="${id}"`,a.product===id)}${btn('CLAIM',`data-claim-product="${id}"`,!a.stored[id])}</div>`)).join('')}</div>${section('Anvil Points',`<div class="vault-grid">${[['speed','Production Speed','+10% speed per point'],['capacity','Product Capacity','+20 stored products per point'],['xp','Experience','+5% claim XP per point']].map(([id,name,text])=>`<div><h4>${name} · ${a.upgrades[id]}</h4><p>${text}</p>${btn('INVEST POINT',`data-anvil-upgrade="${id}"`,E.anvilPoints(c)<1)}</div>`).join('')}</div><div class="save-actions">${btn('BUY POINT · '+E.money(Math.ceil(15*1.25**a.purchased)),'data-anvil-point=""',station!=='anvil'||a.purchased>=40||s.coins<Math.ceil(15*1.25**a.purchased))}${btn('FIND ANVIL','data-find-station="anvil"')}</div>${note('Claim products at the anvil. Spend coins for extra points at the anvil. Products stop at the storage limit and feed equipment stone recipes.')}`)}`;
 if(tab==='furnaces')body=`<div class="inventory-topline"><strong>CONTINUOUS FURNACES</strong>${btn('FIND FOUNDRY','data-find-station="foundry"')}</div><div class="furnace-grid">${s.furnaces.map((f,i)=>section('Furnace '+(i+1),`<div class="furnace-diagram">${itemArt(f.ore)}<span>+</span>${itemArt('charcoal')}<span>→</span>${itemArt(E.furnaceRecipes[f.ore].bar)}</div><div class="sheet-stats">${mini('Ore',f.oreCount+'/200')}${mini('Fuel',f.fuel+'/100')}${mini('Bars',f.output+'/50')}</div><progress value="${f.progress}" max="${E.furnaceRecipes[f.ore].seconds}"></progress><div class="spend-buttons">${Object.keys(E.furnaceRecipes).map(ore=>btn(ore.toUpperCase(),`data-furnace-config="${i}" data-ore="${ore}" class="${ore===f.ore?'primary':''}"`,station!=='foundry'||f.oreCount>0||f.output>0||!E.recipeOpen(s,E.furnaceRecipes[ore]))).join('')}</div><div class="save-actions">${btn('+10 ORE',`data-furnace-load="${i}" data-kind="ore"`,station!=='foundry'||f.oreCount>190)}${btn('+10 FUEL',`data-furnace-load="${i}" data-kind="fuel"`,station!=='foundry'||f.fuel>90)}${btn('CLAIM BARS',`data-furnace-claim="${i}"`,station!=='foundry'||!f.output)}${btn('RETURN INPUTS',`data-furnace-unload="${i}"`,station!=='foundry'||!f.oreCount&&!f.fuel)}</div>`)).join('')}</div>${note('Each batch consumes 3 ore plus fuel. A blacksmith loading the furnace gets double bars. Furnace output stops at 50; queued recipe batches are managed separately.')}`;
 if(tab==='stones'){const gear=[...Object.values(c.loadout),...c.packGear],piece=gear.find(g=>g.uid===v.stoneItem)||gear[0];body=`<div class="master-detail">${section('Equipment',`<div class="ledger-list">${gear.map(g=>btn(itemArt(g.base)+`<strong>${D.ITEMS[g.base].name}</strong><small>${g.upgrades?.length||0}/3 stone slots used</small>`,`data-stone-item="${g.uid}"`)).join('')||note('Craft or equip an item first.')}</div>`)}${section('Upgrade Stones',piece?`<div class="item-heading">${itemArt(piece.base)}<h3>${D.ITEMS[piece.base].name}</h3></div><p>${statText(E.equipmentStats(piece))}</p><div class="stone-slots">${Array.from({length:3},(_,i)=>'<div>'+icon(piece.upgrades?.[i]?'gem':'star',piece.upgrades?.[i]?'#9dc8e5':'#998d76')+'<small>'+(piece.upgrades?.[i]?D.STONES[piece.upgrades[i]].name:'EMPTY')+'</small></div>').join('')}</div><p>Rune slots are separate: ${piece.runes.length}/2.</p>${Object.entries(D.STONES).filter(([,d])=>d.slots.includes(D.EQUIPMENT[piece.base].slot)).map(([id,d])=>`<div class="stone-upgrade"><div class="item-heading">${itemArt('stone-'+id)}<div><h4>${d.name}</h4><p>${statText(d.stats)}</p></div></div>${btn('APPLY STONE',`data-stone="${id}" data-uid="${piece.uid}"`,station!=='anvil'||(piece.upgrades?.length||0)>=3||!E.canPay(s,{['stone-'+id]:1},c))}${btn('RECIPE',`data-open-recipe="stone-${id}"`)}</div>`).join('')}${station!=='anvil'?btn('FIND ANVIL','data-find-station="anvil"'):''}`:note('Select an equipment item.'))}</div>`;}
 return`${tabs([['produce','PRODUCE'],['furnaces','FURNACES'],['stones','UPGRADE STONES']],tab,'data-industry-tab')}${body}`;}
